/* Generated by scripts/split-content.mjs / merge-additions.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"VPC (Virtual Private Cloud)","def":"An isolated virtual network within AWS where you define IP ranges, subnets, route tables, and gateways. The foundation of AWS network architecture.","cat":"Cloud","sub":"AWS SAP"},{"id":"c001","term":"Availability Zone (AZ)","def":"A physically separate data center within an AWS Region, with independent power, cooling, and networking. Designing across AZs provides high availability.","cat":"Cloud","sub":"AWS SAP"},{"id":"c002","term":"Region","def":"A geographic area containing two or more Availability Zones. Data residency, latency, and compliance requirements drive Region selection.","cat":"Cloud","sub":"AWS SAP"},{"id":"c003","term":"IAM (Identity and Access Management)","def":"AWS service for controlling who can do what. Uses users, groups, roles, and policies. Follows the principle of least privilege.","cat":"Cloud","sub":"AWS SAP"},{"id":"c004","term":"IAM Role","def":"An identity with permission policies that can be assumed by services, applications, or users. Preferred over long-lived credentials for cross-account and service access.","cat":"Cloud","sub":"AWS SAP"},{"id":"c005","term":"STS (Security Token Service)","def":"Issues temporary, limited-privilege credentials for IAM roles. Powers cross-account access and federation.","cat":"Cloud","sub":"AWS SAP"},{"id":"c006","term":"S3 (Simple Storage Service)","def":"Object storage with 11 nines of durability. Supports versioning, lifecycle policies, cross-region replication, and multiple storage classes.","cat":"Cloud","sub":"AWS SAP"},{"id":"c007","term":"S3 Storage Classes","def":"Standard, Intelligent-Tiering, Standard-IA, One Zone-IA, Glacier Instant Retrieval, Glacier Flexible Retrieval, Glacier Deep Archive — cost decreases as retrieval latency increases.","cat":"Cloud","sub":"AWS SAP"},{"id":"c008","term":"CloudFront","def":"AWS CDN that caches content at edge locations worldwide. Reduces latency and offloads origin servers. Supports signed URLs, Lambda@Edge, and Origin Access Control.","cat":"Cloud","sub":"AWS SAP"},{"id":"c009","term":"Route 53","def":"DNS service with health checks, routing policies (simple, weighted, latency, failover, geolocation, multivalue), and domain registration.","cat":"Cloud","sub":"AWS SAP"},{"id":"c010","term":"Auto Scaling Group (ASG)","def":"Automatically adjusts the number of EC2 instances based on demand using scaling policies. Maintains desired, minimum, and maximum capacity.","cat":"Cloud","sub":"AWS SAP"},{"id":"c011","term":"Elastic Load Balancer (ELB)","def":"Distributes traffic across targets. ALB operates at Layer 7 (HTTP), NLB at Layer 4 (TCP/UDP), GLB for third-party appliances.","cat":"Cloud","sub":"AWS SAP"},{"id":"c012","term":"Lambda","def":"Serverless compute that runs code in response to events. Billed per invocation and duration. Maximum 15-minute execution, 10 GB memory.","cat":"Cloud","sub":"AWS SAP"},{"id":"c013","term":"ECS / EKS","def":"Container orchestration services. ECS is AWS-native, EKS is managed Kubernetes. Both run on EC2 or Fargate (serverless containers).","cat":"Cloud","sub":"AWS SAP"},{"id":"c014","term":"RDS (Relational Database Service)","def":"Managed relational databases (MySQL, PostgreSQL, MariaDB, Oracle, SQL Server). Supports Multi-AZ for HA, read replicas for scaling reads.","cat":"Cloud","sub":"AWS SAP"},{"id":"c015","term":"Aurora","def":"AWS-built MySQL/PostgreSQL-compatible engine with up to 5x throughput. Storage auto-scales to 128 TB, replicates 6 copies across 3 AZs.","cat":"Cloud","sub":"AWS SAP"},{"id":"c016","term":"DynamoDB","def":"Fully managed NoSQL key-value and document database. Single-digit millisecond latency. Supports on-demand and provisioned capacity, global tables, and DAX caching.","cat":"Cloud","sub":"AWS SAP"},{"id":"c017","term":"ElastiCache","def":"Managed Redis or Memcached for in-memory caching. Reduces database load and improves read performance.","cat":"Cloud","sub":"AWS SAP"},{"id":"c018","term":"CloudFormation","def":"Infrastructure as Code service using JSON or YAML templates. Manages resource stacks with drift detection, change sets, and rollback.","cat":"Cloud","sub":"AWS SAP"},{"id":"c019","term":"Well-Architected Framework","def":"Six pillars guiding AWS architecture: Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability.","cat":"Cloud","sub":"AWS SAP"},{"id":"c020","term":"AWS Organizations","def":"Centralized management of multiple AWS accounts. Uses Service Control Policies (SCPs) to set permission boundaries across the organization.","cat":"Cloud","sub":"AWS SAP"},{"id":"c021","term":"Transit Gateway","def":"Hub that connects VPCs, VPNs, and Direct Connect in a hub-and-spoke model. Replaces complex VPC peering meshes.","cat":"Cloud","sub":"AWS SAP"},{"id":"c022","term":"Direct Connect","def":"Dedicated private network connection from on-premises to AWS. Lower latency and more consistent throughput than internet-based VPN.","cat":"Cloud","sub":"AWS SAP"},{"id":"c023","term":"KMS (Key Management Service)","def":"Creates and manages encryption keys. Integrates with most AWS services for at-rest encryption. Supports key rotation and custom key stores.","cat":"Cloud","sub":"AWS SAP"},{"id":"c024","term":"CloudTrail","def":"Records API calls across your AWS account. Essential for auditing, compliance, and security investigation.","cat":"Cloud","sub":"AWS SAP"},{"id":"c025","term":"CloudWatch","def":"Monitoring and observability service. Collects metrics, logs, and traces. Alarms trigger Auto Scaling, SNS notifications, or Lambda functions.","cat":"Cloud","sub":"AWS SAP"},{"id":"c026","term":"SNS / SQS","def":"SNS is pub/sub messaging (fan-out). SQS is a message queue (decoupling). Together they build resilient event-driven architectures.","cat":"Cloud","sub":"AWS SAP"},{"id":"c027","term":"EventBridge","def":"Serverless event bus that routes events between AWS services, SaaS apps, and custom applications using rules and event patterns.","cat":"Cloud","sub":"AWS SAP"},{"id":"c028","term":"Kinesis","def":"Real-time streaming data platform. Kinesis Data Streams for custom processing, Firehose for delivery to S3/Redshift/OpenSearch, Analytics for SQL on streams.","cat":"Cloud","sub":"AWS SAP"},{"id":"c029","term":"Cost Explorer / Budgets","def":"Cost Explorer visualizes spending patterns. Budgets set alerts on cost or usage thresholds. Together they enable cost governance.","cat":"Cloud","sub":"AWS SAP"},{"id":"c030","term":"GCP Project","def":"The fundamental organizational unit in Google Cloud. Resources, billing, APIs, and IAM are scoped to a project.","cat":"Cloud","sub":"GCP PCA"},{"id":"c031","term":"GCP Organization / Folder","def":"Organization is the root node for all projects. Folders group projects and apply policies hierarchically.","cat":"Cloud","sub":"GCP PCA"},{"id":"c032","term":"Compute Engine","def":"GCP IaaS virtual machines. Supports preemptible and spot VMs for cost savings, custom machine types, and sole-tenant nodes.","cat":"Cloud","sub":"GCP PCA"},{"id":"c033","term":"GKE (Google Kubernetes Engine)","def":"Managed Kubernetes service. Supports Autopilot (fully managed) and Standard (node-level control) modes.","cat":"Cloud","sub":"GCP PCA"},{"id":"c034","term":"Cloud Run","def":"Serverless container platform. Runs any containerized workload that listens on HTTP. Scales to zero, billed per request.","cat":"Cloud","sub":"GCP PCA"},{"id":"c035","term":"Cloud Functions","def":"Event-driven serverless functions. Triggered by HTTP, Pub/Sub, Cloud Storage events, Firestore changes, and more.","cat":"Cloud","sub":"GCP PCA"},{"id":"c036","term":"Cloud Storage","def":"Object storage with four classes: Standard, Nearline (30-day min), Coldline (90-day min), Archive (365-day min). Strongly consistent.","cat":"Cloud","sub":"GCP PCA"},{"id":"c037","term":"Cloud SQL / Cloud Spanner","def":"Cloud SQL: managed MySQL, PostgreSQL, SQL Server. Spanner: globally distributed, strongly consistent relational database with 99.999% SLA.","cat":"Cloud","sub":"GCP PCA"},{"id":"c038","term":"BigQuery","def":"Serverless data warehouse for analytics. Columnar storage, SQL interface, supports streaming inserts and federated queries across sources.","cat":"Cloud","sub":"GCP PCA"},{"id":"c039","term":"Pub/Sub","def":"Global messaging and event streaming service. Decouples publishers and subscribers. At-least-once delivery, supports push and pull.","cat":"Cloud","sub":"GCP PCA"},{"id":"c040","term":"VPC in GCP","def":"Global resource spanning all regions. Subnets are regional. Supports Shared VPC (cross-project networking) and VPC Peering.","cat":"Cloud","sub":"GCP PCA"},{"id":"c041","term":"Cloud IAM in GCP","def":"Binds members to roles on resources. Roles are primitive (owner/editor/viewer), predefined, or custom. Policy inheritance follows the resource hierarchy.","cat":"Cloud","sub":"GCP PCA"},{"id":"c042","term":"Cloud Armor","def":"DDoS protection and WAF for HTTP(S) load balancers. Supports IP allowlists/denylists, geo-based rules, and preconfigured WAF rules.","cat":"Cloud","sub":"GCP PCA"},{"id":"c043","term":"Anthos","def":"Platform for managing workloads across GKE, on-premises, and other clouds. Uses a consistent Kubernetes-based control plane.","cat":"Cloud","sub":"GCP PCA"},{"id":"c044","term":"Cloud CDN (GCP)","def":"Content delivery network integrated with HTTP(S) Load Balancing. Caches content at Google's global edge.","cat":"Cloud","sub":"GCP PCA"},{"id":"c045","term":"Azure Subscription","def":"A billing and access container for Azure resources. Resources are grouped into Resource Groups within a subscription.","cat":"Cloud","sub":"Azure SA"},{"id":"c046","term":"Resource Group","def":"A logical container for Azure resources that share a lifecycle. Policies, RBAC, and tags are commonly applied at this level.","cat":"Cloud","sub":"Azure SA"},{"id":"c047","term":"Azure AD / Entra ID","def":"Cloud identity and access management service. Handles authentication, single sign-on, conditional access, and MFA.","cat":"Cloud","sub":"Azure SA"},{"id":"c048","term":"Azure RBAC","def":"Role-Based Access Control at the management group, subscription, resource group, or resource level. Built-in roles plus custom role support.","cat":"Cloud","sub":"Azure SA"},{"id":"c049","term":"Virtual Network (VNet)","def":"Isolated network in Azure with subnets, NSGs, route tables, and peering. VNet peering connects VNets across regions.","cat":"Cloud","sub":"Azure SA"},{"id":"c050","term":"Azure Load Balancer / App Gateway","def":"Load Balancer operates at Layer 4. Application Gateway is a Layer 7 load balancer with WAF, URL routing, and SSL termination.","cat":"Cloud","sub":"Azure SA"},{"id":"c051","term":"Azure Functions","def":"Serverless compute triggered by events. Supports consumption (scale-to-zero) and premium (pre-warmed) plans.","cat":"Cloud","sub":"Azure SA"},{"id":"c052","term":"Azure Kubernetes Service (AKS)","def":"Managed Kubernetes with integrated CI/CD, monitoring, and Azure AD integration. Control plane is free; you pay for nodes.","cat":"Cloud","sub":"Azure SA"},{"id":"c053","term":"Cosmos DB","def":"Globally distributed, multi-model NoSQL database. Supports five consistency levels from strong to eventual. Single-digit millisecond latency.","cat":"Cloud","sub":"Azure SA"},{"id":"c054","term":"Azure SQL / SQL Managed Instance","def":"Azure SQL Database is a fully managed PaaS. Managed Instance provides near-complete SQL Server engine compatibility for lift-and-shift.","cat":"Cloud","sub":"Azure SA"},{"id":"c055","term":"Blob Storage","def":"Azure object storage with Hot, Cool, Cold, and Archive access tiers. Supports immutable storage, versioning, and lifecycle management.","cat":"Cloud","sub":"Azure SA"},{"id":"c056","term":"Azure Front Door","def":"Global load balancer and CDN with WAF, SSL offloading, URL-based routing, and session affinity. Routes to the fastest healthy backend.","cat":"Cloud","sub":"Azure SA"},{"id":"c057","term":"ExpressRoute","def":"Dedicated private connection from on-premises to Azure via a connectivity provider. Does not traverse the public internet.","cat":"Cloud","sub":"Azure SA"},{"id":"c058","term":"ARM Templates / Bicep","def":"Infrastructure as Code for Azure. ARM templates are JSON; Bicep is a cleaner DSL that compiles to ARM. Both deploy and manage resource stacks.","cat":"Cloud","sub":"Azure SA"},{"id":"c059","term":"Azure Monitor / Log Analytics","def":"Azure Monitor collects metrics and logs. Log Analytics workspace stores and queries logs using KQL (Kusto Query Language).","cat":"Cloud","sub":"Azure SA"},{"id":"c060","term":"Azure Policy","def":"Enforces organizational standards across resources. Policies can audit, deny, or remediate non-compliant configurations.","cat":"Cloud","sub":"Azure SA"},{"id":"c061","term":"Azure Landing Zone","def":"A prescriptive architecture for setting up a multi-subscription Azure environment with governance, networking, identity, and security baselines.","cat":"Cloud","sub":"Azure SA"},{"id":"c062","term":"Shared Responsibility Model","def":"The cloud provider secures the infrastructure; the customer secures what they put on it. The boundary shifts depending on IaaS, PaaS, or SaaS.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c063","term":"IaaS / PaaS / SaaS","def":"Infrastructure, Platform, and Software as a Service. Each moves more responsibility to the provider and less to the customer.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c064","term":"Multi-Region Architecture","def":"Deploying across multiple geographic regions for disaster recovery and low latency. Requires data replication, DNS-based routing, and conflict resolution.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c065","term":"RPO / RTO","def":"Recovery Point Objective: how much data loss is acceptable. Recovery Time Objective: how long until service is restored. Together they define DR requirements.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c066","term":"Infrastructure as Code (IaC)","def":"Managing and provisioning infrastructure through machine-readable configuration files rather than manual processes. Enables version control, testing, and repeatability.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c067","term":"GitOps","def":"Operational model where Git is the single source of truth for declarative infrastructure and applications. Changes are applied via pull requests and automated reconciliation.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c068","term":"Service Mesh","def":"Infrastructure layer handling service-to-service communication. Provides mutual TLS, traffic management, observability, and retries. Examples: Istio, Linkerd.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c069","term":"CAP Theorem","def":"A distributed data system can guarantee at most two of Consistency, Availability, and Partition tolerance. Network partitions are unavoidable, so the real choice is C or A during a partition.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c070","term":"Eventual Consistency","def":"After a write, reads may not immediately return the latest value, but the system converges over time. Used in highly available distributed systems.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c071","term":"Blue/Green Deployment","def":"Maintaining two identical environments. Traffic is switched from the current (blue) to the new (green) once validated. Enables instant rollback.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c072","term":"Canary Deployment","def":"Rolling out a change to a small subset of users or instances before full rollout. Limits blast radius if the change introduces an issue.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c073","term":"12-Factor App","def":"Methodology for building SaaS applications. Key principles: config in environment, stateless processes, port binding, disposability, dev/prod parity, logs as event streams.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c074","term":"FinOps","def":"Practice of bringing financial accountability to cloud spending. Combines engineering, finance, and business to optimize cloud value.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c075","term":"VPC Endpoints / PrivateLink","def":"Private connectivity from a VPC to AWS services without traversing the internet. Gateway endpoints (S3, DynamoDB) use route table entries and are free. Interface endpoints use an ENI with a private IP and are billed hourly plus per GB.","cat":"Cloud","sub":"AWS SAP"},{"id":"c076","term":"NAT Gateway","def":"Managed service allowing instances in private subnets to initiate outbound internet connections while blocking inbound ones. Zonal resource — one per AZ for high availability. Charged hourly plus per GB processed, which makes it a common source of surprise cost.","cat":"Cloud","sub":"AWS SAP"},{"id":"c077","term":"Security Groups vs. Network ACLs","def":"Security groups are stateful, attach to ENIs, and support allow rules only. Network ACLs are stateless, attach to subnets, support allow and deny, and are evaluated in rule-number order. Both are evaluated; traffic must pass each.","cat":"Cloud","sub":"AWS SAP"},{"id":"c078","term":"EBS Volume Types","def":"gp3 (general purpose SSD, independently provisioned IOPS and throughput), io1/io2 (provisioned IOPS SSD for latency-sensitive databases), st1 (throughput-optimized HDD for streaming workloads), sc1 (cold HDD for infrequent access).","cat":"Cloud","sub":"AWS SAP"},{"id":"c079","term":"EFS / FSx","def":"EFS is a fully managed NFS file system that scales elastically and mounts across AZs. FSx provides managed third-party file systems: FSx for Windows File Server (SMB), FSx for Lustre (high-performance computing), FSx for NetApp ONTAP, FSx for OpenZFS.","cat":"Cloud","sub":"AWS SAP"},{"id":"c080","term":"Redshift","def":"Managed petabyte-scale data warehouse using columnar storage and massively parallel processing. Redshift Spectrum queries data directly in S3 without loading it. Suited to complex analytical queries over structured data, not high-concurrency transactional workloads.","cat":"Cloud","sub":"AWS SAP"},{"id":"c081","term":"Step Functions","def":"Serverless orchestration service that coordinates multiple AWS services into state machines defined in Amazon States Language. Handles retries, error catching, parallel branches, and long-running workflows that exceed a single Lambda's execution limit.","cat":"Cloud","sub":"AWS SAP"},{"id":"c082","term":"Secrets Manager vs. Parameter Store","def":"Secrets Manager stores credentials with built-in automatic rotation and cross-region replication, billed per secret. Systems Manager Parameter Store offers a free standard tier for configuration and SecureString parameters, without native rotation.","cat":"Cloud","sub":"AWS SAP"},{"id":"c083","term":"AWS Config","def":"Records the configuration of resources over time and evaluates them against rules. Answers \"what did this resource look like last Tuesday\" and \"which resources are non-compliant.\" Distinct from CloudTrail, which records API calls rather than resource state.","cat":"Cloud","sub":"AWS SAP"},{"id":"c084","term":"GuardDuty / Security Hub / Macie","def":"GuardDuty is a managed threat detection service analyzing CloudTrail, VPC Flow Logs, and DNS logs. Security Hub aggregates findings across security services into a single view. Macie discovers and classifies sensitive data in S3.","cat":"Cloud","sub":"AWS SAP"},{"id":"c085","term":"EC2 Purchasing Options","def":"On-Demand (no commitment, highest rate), Reserved Instances (1 or 3 year commitment to instance attributes), Savings Plans (commitment to hourly spend, more flexible than RIs), Spot (spare capacity at steep discount, interruptible with a two-minute warning), Dedicated Hosts (physical server for licensing or compliance).","cat":"Cloud","sub":"AWS SAP"},{"id":"c086","term":"Global Accelerator","def":"Provides two static anycast IP addresses that route traffic over the AWS backbone to the nearest healthy endpoint. Improves performance for non-HTTP protocols and enables fast regional failover. CloudFront caches content; Global Accelerator does not.","cat":"Cloud","sub":"AWS SAP"},{"id":"c087","term":"Service Account (GCP)","def":"A special identity used by applications and VMs rather than people. Can be granted IAM roles and impersonated. Best practice is one service account per workload with narrowly scoped roles, avoiding downloaded key files where possible.","cat":"Cloud","sub":"GCP PCA"},{"id":"c088","term":"Organization Policy Service","def":"Applies constraints across the resource hierarchy — restricting which regions can be used, disabling external IPs, or blocking service account key creation. Constraints are guardrails on configuration, distinct from IAM, which governs who may act.","cat":"Cloud","sub":"GCP PCA"},{"id":"c089","term":"Cloud Interconnect / Cloud VPN","def":"Cloud VPN establishes an IPsec tunnel over the public internet. Dedicated Interconnect provides a direct physical connection to Google's network; Partner Interconnect goes through a supported provider. Interconnect offers higher bandwidth and more predictable latency.","cat":"Cloud","sub":"GCP PCA"},{"id":"c090","term":"Cloud Load Balancing","def":"Google's load balancing is software-defined and global for HTTP(S), SSL Proxy, and TCP Proxy — a single anycast IP serves clients worldwide. Internal and network load balancers are regional. No pre-warming is required.","cat":"Cloud","sub":"GCP PCA"},{"id":"c091","term":"Bigtable","def":"Petabyte-scale wide-column NoSQL database for high-throughput, low-latency workloads such as time-series, IoT, and ad tech. Single-row transactions only, no SQL joins. Chosen for write volume and scan performance rather than relational querying.","cat":"Cloud","sub":"GCP PCA"},{"id":"c092","term":"Firestore","def":"Serverless document database with real-time listeners and offline client sync. Native mode for new applications; Datastore mode for compatibility with legacy Datastore workloads. Strongly consistent, with automatic multi-region replication.","cat":"Cloud","sub":"GCP PCA"},{"id":"c093","term":"Dataflow","def":"Managed service for stream and batch data processing built on Apache Beam. One pipeline definition serves both modes. Autoscales workers and handles windowing, watermarks, and late-arriving data for event-time processing.","cat":"Cloud","sub":"GCP PCA"},{"id":"c094","term":"Dataproc","def":"Managed Hadoop and Spark clusters that start in around ninety seconds and are billed per second. Designed for lift-and-shift of existing Spark or Hadoop jobs; ephemeral job-scoped clusters are the cost-efficient pattern.","cat":"Cloud","sub":"GCP PCA"},{"id":"c095","term":"Cloud KMS / CMEK","def":"Cloud KMS creates and manages cryptographic keys with rotation schedules and IAM-controlled access. Customer-Managed Encryption Keys let a customer supply the key protecting data in Google-managed services, so revoking the key renders data unreadable.","cat":"Cloud","sub":"GCP PCA"},{"id":"c096","term":"VPC Service Controls","def":"Defines a service perimeter around Google-managed resources to mitigate data exfiltration. Even a caller with valid IAM credentials cannot move data across the perimeter. Complements IAM rather than replacing it.","cat":"Cloud","sub":"GCP PCA"},{"id":"c097","term":"Cloud Operations Suite","def":"Formerly Stackdriver. Cloud Logging aggregates logs with sinks to BigQuery, Cloud Storage, or Pub/Sub. Cloud Monitoring handles metrics, uptime checks, and alerting. Cloud Trace and Cloud Profiler cover distributed tracing and performance.","cat":"Cloud","sub":"GCP PCA"},{"id":"c098","term":"Committed Use / Sustained Use Discounts","def":"Committed Use Discounts trade a one or three year resource commitment for a substantial rate reduction. Sustained Use Discounts apply automatically as a VM runs a larger share of the month, with no commitment required.","cat":"Cloud","sub":"GCP PCA"},{"id":"c099","term":"Management Group","def":"A container above subscriptions used to organize them into a hierarchy. Policies and RBAC assignments applied at a management group are inherited by all subscriptions beneath it. The root management group covers the whole tenant.","cat":"Cloud","sub":"Azure SA"},{"id":"c100","term":"Managed Identity","def":"An Entra ID identity automatically managed by Azure that lets a resource authenticate to services without stored credentials. System-assigned identities share the resource lifecycle; user-assigned identities are standalone and reusable across resources.","cat":"Cloud","sub":"Azure SA"},{"id":"c101","term":"Conditional Access","def":"Entra ID policy engine evaluating signals — user, device state, location, application, risk level — to permit, block, or require additional controls such as MFA. The primary enforcement point for Zero Trust access in Azure.","cat":"Cloud","sub":"Azure SA"},{"id":"c102","term":"Key Vault","def":"Managed store for secrets, certificates, and cryptographic keys, with HSM-backed tiers. Supports soft delete and purge protection, access via RBAC or vault access policies, and integration with managed identities so applications never hold credentials.","cat":"Cloud","sub":"Azure SA"},{"id":"c103","term":"Network Security Group / Application Security Group","def":"NSGs contain allow and deny rules filtering traffic at subnet or NIC level, evaluated by priority. Application Security Groups let rules reference logical groupings of NICs by role instead of hard-coded IP ranges.","cat":"Cloud","sub":"Azure SA"},{"id":"c104","term":"Azure Bastion","def":"Managed PaaS jump host providing RDP and SSH to VMs through the Azure portal over TLS. Removes the need for public IPs on VMs or a self-managed bastion host, reducing exposed attack surface.","cat":"Cloud","sub":"Azure SA"},{"id":"c105","term":"Availability Sets / Availability Zones","def":"Availability Sets distribute VMs across fault and update domains within a single datacenter, protecting against rack and maintenance failures. Availability Zones are physically separate datacenters within a region, protecting against datacenter-level failure and carrying a higher SLA.","cat":"Cloud","sub":"Azure SA"},{"id":"c106","term":"App Service","def":"Managed PaaS for hosting web applications, APIs, and mobile backends. Provides deployment slots for staged releases and swap, autoscaling, custom domains, and managed certificates. Runs on an App Service Plan that determines compute and cost.","cat":"Cloud","sub":"Azure SA"},{"id":"c107","term":"Service Bus / Event Grid / Event Hubs","def":"Service Bus is enterprise messaging with queues, topics, sessions, and transactions. Event Grid is a reactive event routing service for discrete events. Event Hubs is a high-throughput streaming ingestion service for telemetry and log pipelines.","cat":"Cloud","sub":"Azure SA"},{"id":"c108","term":"Azure Site Recovery / Azure Backup","def":"Site Recovery replicates VMs to a secondary region for disaster recovery, with orchestrated failover and test failover. Azure Backup handles point-in-time restore of files, VMs, and databases through a Recovery Services vault.","cat":"Cloud","sub":"Azure SA"},{"id":"c109","term":"Microsoft Defender for Cloud","def":"Cloud security posture management and workload protection. Provides a secure score, surfaces misconfigurations against benchmarks, and offers threat protection plans for servers, storage, databases, and containers across Azure and connected clouds.","cat":"Cloud","sub":"Azure SA"},{"id":"c110","term":"SLI / SLO / SLA","def":"A Service Level Indicator is the measured signal (latency, error rate, availability). A Service Level Objective is the internal target for that indicator. A Service Level Agreement is the external contract with financial consequences. SLOs should be stricter than SLAs.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c111","term":"Error Budget","def":"The permitted amount of unreliability implied by an SLO — a 99.9% target allows roughly 43 minutes of failure per month. Spending the budget slows feature release; unspent budget signals capacity for more aggressive change.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c112","term":"Observability","def":"The ability to infer a system's internal state from its outputs. The three signals are metrics (aggregate numeric time series), logs (discrete events), and traces (request paths across services). Monitoring answers known questions; observability supports unknown ones.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c113","term":"Idempotency","def":"The property that repeating an operation produces the same result as performing it once. Essential in distributed systems, where at-least-once delivery means consumers must tolerate duplicate messages without duplicating side effects.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c114","term":"Circuit Breaker","def":"Resilience pattern that stops calling a failing dependency after a threshold of errors, returning fast failures instead. Moves to half-open after a cooldown to test recovery. Prevents a slow downstream service from exhausting upstream connection pools.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c115","term":"Immutable Infrastructure","def":"Servers are never modified after deployment. Changes produce a new image and a replacement instance. Eliminates configuration drift and makes rollback a matter of redeploying the previous image.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c116","term":"Strangler Fig Pattern","def":"Incremental migration approach where new functionality is built alongside a legacy system and traffic is progressively routed away from the old system until it can be retired. Avoids high-risk big-bang rewrites.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c117","term":"Chaos Engineering","def":"Deliberately injecting failures — instance termination, latency, dependency errors — into a system to validate resilience assumptions. Run against a steady-state hypothesis, ideally in production with a controlled blast radius.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c118","term":"Data Gravity / Egress Cost","def":"Large datasets attract applications and services to their location, and providers charge for data leaving their network while inbound transfer is typically free. Together these create practical lock-in and shape multi-cloud architecture decisions.","cat":"Cloud","sub":"Cross-Cloud"},{"id":"c119","term":"Workload Identity Federation","def":"Allows a workload outside a cloud provider to exchange a trusted external token for short-lived provider credentials, removing the need for long-lived stored keys. Implemented as IAM roles for service accounts, workload identity pools, or federated credentials depending on provider.","cat":"Cloud","sub":"Cross-Cloud"}],"questions":[{"cat":"Cloud","sub":"AWS SAP","stem":"A company needs to serve static assets to users globally with the lowest latency. Which combination should the architect recommend?","choices":["RDS read replicas with Route 53","S3 with CloudFront distribution","EBS volumes with cross-region replication","EC2 instances in every region"],"answer":1,"label":"S3 + CloudFront","why":"S3 provides durable object storage and CloudFront caches at edge locations worldwide, minimizing latency without managing servers.","id":"q001","n":1},{"cat":"Cloud","sub":"Azure SA","stem":"A company migrating SQL Server databases to Azure needs near-complete engine compatibility with minimal application changes. They should choose:","choices":["Cosmos DB","Azure Database for PostgreSQL","Azure SQL Managed Instance","Azure SQL Database"],"answer":2,"label":"SQL Managed Instance","why":"Managed Instance provides near-complete SQL Server engine compatibility including SQL Agent, CLR, and cross-database queries, unlike Azure SQL Database.","id":"q016","n":16},{"cat":"Cloud","sub":"Cross-Cloud","stem":"Under the shared responsibility model, which of the following is always the customer's responsibility regardless of service model?","choices":["Network switch maintenance","Hypervisor patching","Data classification and access control","Physical data center security"],"answer":2,"label":"Data classification","why":"The customer always owns their data, including classifying it and controlling who can access it, across IaaS, PaaS, and SaaS.","id":"q021","n":21},{"cat":"Cloud","sub":"GCP PCA","stem":"A company needs a globally distributed database with strong consistency and a 99.999% availability SLA for a financial application. The best GCP service is:","choices":["Cloud SQL with read replicas","Firestore in Datastore mode","Bigtable","Cloud Spanner"],"answer":3,"label":"Cloud Spanner","why":"Spanner is the only GCP database offering both global distribution and strong consistency with a 99.999% SLA.","id":"q011","n":11},{"cat":"Cloud","sub":"AWS SAP","stem":"An application running on EC2 needs to access an S3 bucket in another AWS account without long-lived credentials. The correct approach is:","choices":["Use the root account credentials of the other account","Store the other account's credentials in Systems Manager Parameter Store","Create an IAM user in the other account and share the access keys","Create a cross-account IAM role and have the application assume it via STS"],"answer":3,"label":"Cross-account IAM role","why":"IAM roles with STS provide temporary credentials, eliminating the security risk of shared long-lived access keys.","id":"q002","n":2},{"cat":"Cloud","sub":"Azure SA","stem":"An architect needs to enforce that all storage accounts in the organization use HTTPS-only and are in specific regions. The mechanism is:","choices":["Resource locks","Azure Policy with deny effect","Network security groups","Azure RBAC custom roles"],"answer":1,"label":"Azure Policy","why":"Azure Policy evaluates resource configurations against rules and can deny non-compliant deployments. RBAC controls who can act, not how resources are configured.","id":"q017","n":17},{"cat":"Cloud","sub":"Cross-Cloud","stem":"An application requires an RPO of zero and an RTO of under one minute. The architecture pattern that meets this is:","choices":["Warm standby with periodic snapshots","Nightly backups to another region","Active-active multi-region with synchronous replication","Pilot light with manual scaling"],"answer":2,"label":"Active-active multi-region","why":"Zero RPO requires synchronous replication, and sub-minute RTO requires an always-running environment processing traffic in both regions.","id":"q022","n":22},{"cat":"Cloud","sub":"GCP PCA","stem":"A team needs to run a containerized web application that scales to zero when idle and requires no cluster management. They should use:","choices":["App Engine Flex","Cloud Run","GKE Autopilot","Compute Engine with a container-optimized OS"],"answer":1,"label":"Cloud Run","why":"Cloud Run runs containers serverlessly, scales to zero, and requires no cluster. GKE Autopilot still maintains a cluster.","id":"q012","n":12},{"cat":"Cloud","sub":"AWS SAP","stem":"A solutions architect is designing a highly available web application. The architecture should survive the loss of an entire Availability Zone. The minimum design requires:","choices":["A single EC2 instance with an Elastic IP","EC2 instances in two Regions with Route 53 failover","EC2 instances in two AZs behind an Application Load Balancer","A single AZ with Auto Scaling"],"answer":2,"label":"Multi-AZ with ALB","why":"Multi-AZ deployment ensures that if one AZ fails, the load balancer routes traffic to healthy instances in the remaining AZ.","id":"q003","n":3},{"cat":"Cloud","sub":"Azure SA","stem":"A global application needs to route users to the nearest healthy backend with automatic failover. The correct service is:","choices":["Azure Load Balancer","Azure Traffic Manager with weighted routing","Azure Application Gateway","Azure Front Door"],"answer":3,"label":"Azure Front Door","why":"Front Door is a global Layer 7 load balancer with CDN, WAF, and intelligent routing to the nearest healthy backend.","id":"q018","n":18}],"meta":{"total":90,"free":10,"split":true}};
